package org.codex.nfsugpreview;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class ObjImageTest {public static void main(String[] args)throws Exception{byte[] vram=Files.readAllBytes(Paths.get(args[0])),palette=Files.readAllBytes(Paths.get(args[1])),vbefore=vram.clone(),pbefore=palette.clone();int count,accepted=0,rejected=0,texels=0;try(DataInputStream in=new DataInputStream(new FileInputStream(args[2]))){if(in.readInt()!=0x314a424f)throw new AssertionError("Header");count=in.readInt();for(int ci=0;ci<count;ci++){int kind=in.readInt(),a=in.readInt(),b=in.readInt(),c=in.readInt(),display=in.readInt();int[] matrix={in.readInt(),in.readInt(),in.readInt(),in.readInt()},before=matrix.clone();boolean expected=in.readInt()!=0;int width=in.readInt(),height=in.readInt();int[] reference=new int[width*height];for(int i=0;i<reference.length;i++)reference[i]=in.readInt();NativeObjImage.Image image=null;boolean good=true;try{image=kind==0?NativeObjImage.regular(vram,palette,a,b,c,display):NativeObjImage.affine(vram,palette,a,b,c,display,matrix);}catch(IllegalArgumentException invalid){good=false;}if(good!=expected)throw new AssertionError("Acceptance "+ci);if(!Arrays.equals(matrix,before))throw new AssertionError("Matrix mutation");if(good){accepted++;if(image.width!=width||image.height!=height||!Arrays.equals(image.rgba(),reference))throw new AssertionError("OBJ pixels "+ci);int[] copy=image.rgba();copy[0]^=1;if(!Arrays.equals(image.rgba(),reference))throw new AssertionError("Borrowed output");texels+=reference.length;}else rejected++;}if(in.read()!=-1)throw new AssertionError("Trailing cases");}if(!Arrays.equals(vram,vbefore)||!Arrays.equals(palette,pbefore))throw new AssertionError("Input mutation");System.out.println("PASS_OBJ_IMAGE cases="+count+" accepted="+accepted+" rejected="+rejected+" exact_rgba_texels="+texels+" inputs_immutable=true output_owned=true");}}
